head.script:
scwin.onpageload = function () {
    var top = $p.top();
    if (!top || !top.scwin || typeof top.scwin.log !== "function") {
        return;
    }
    top.scwin.log("[wframe 자식] printFormInfo_WAEA-1063_(WSQ-6421)_wf.xml onpageload");
    // 자체 scope 를 갖는 wframe 이므로 $p 는 자기 화면을 가리킨다. 선언이 없어 빈 객체.
    top.scwin.log("  자식 화면에서 $p.getPrintFormInfo() = " + JSON.stringify($p.getPrintFormInfo()));
    top.scwin.log("  자식 컴포넌트 좌표 inp_wf.getPrintFormPosition() = " + JSON.stringify(inp_wf.getPrintFormPosition()));
};
